public sealed class NotificationOutboxEmergencyFlowTests
{
    [Fact]
    public async Task OutboxUpdatesAreVisibleInEmergencyStatusAndOperationalDashboardWithoutSideEffects()
    {
        var stores = new Stores(); await using WebApplicationFactory<Program> factory = CreateFactory(stores); HttpClient admin = factory.CreateClient(); HttpClient rider = factory.CreateClient(); User adminUser = await AuthenticateAsync(admin, "flow-admin@example.com", UserRole.Admin, stores); User riderUser = await AuthenticateAsync(rider, "flow-rider@example.com", UserRole.Rider, stores);
        Incident incident = SeedEmergency(stores, riderUser.Id); AlertDispatchRequest alert = stores.Alerts.Items.Single();
        NotificationDeliveryAttempt preparedToSend = Attempt(riderUser.Id, incident.Id, alert.Id, NotificationDeliveryStatus.Prepared, "contact-1"); NotificationDeliveryAttempt preparedToFail = Attempt(riderUser.Id, incident.Id, alert.Id, NotificationDeliveryStatus.Prepared, "contact-2"); NotificationDeliveryAttempt cancelled = Attempt(riderUser.Id, incident.Id, alert.Id, NotificationDeliveryStatus.Cancelled, "contact-3"); NotificationDeliveryAttempt alreadySent = Attempt(riderUser.Id, incident.Id, alert.Id, NotificationDeliveryStatus.SimulatedSent, "contact-4"); stores.Attempts.Items.AddRange([preparedToSend, preparedToFail, cancelled, alreadySent]);
        Incident originalIncident = Clone(incident); AlertDispatchRequest originalAlert = Clone(alert);

        await admin.PostAsJsonAsync("/api/v1/admin/notifications/outbox/run", new RunNotificationOutboxRequest(1, false));
        await admin.PostAsJsonAsync("/api/v1/admin/notifications/outbox/run", new RunNotificationOutboxRequest(1, true));
        string statusAfterFailure = await (await rider.GetAsync($"/api/v1/rider/emergencies/{incident.Id}/status")).Content.ReadAsStringAsync();
        string dashboardAfterFailure = await (await admin.GetAsync("/api/v1/admin/dashboard/summary")).Content.ReadAsStringAsync();

        preparedToSend.Status.Should().Be(NotificationDeliveryStatus.SimulatedSent);
        preparedToFail.Status.Should().Be(NotificationDeliveryStatus.Failed);
        preparedToFail.FailureReason.Should().Be("simulated_failure_requested");
        cancelled.Status.Should().Be(NotificationDeliveryStatus.Cancelled);
        alreadySent.Status.Should().Be(NotificationDeliveryStatus.SimulatedSent);
        statusAfterFailure.Should().Contain("\"total\":4").And.Contain("\"prepared\":0").And.Contain("\"simulatedSent\":2").And.Contain("\"failed\":1").And.Contain("\"cancelled\":1");
        dashboardAfterFailure.Should().Contain("\"prepared\":0").And.Contain("\"simulatedSent\":2").And.Contain("\"failed\":1").And.Contain("\"cancelled\":1");

        await admin.PostAsJsonAsync("/api/v1/admin/notifications/outbox/retry-failed", new RetryFailedNotificationOutboxRequest(20));
        string statusAfterRetry = await (await rider.GetAsync($"/api/v1/rider/emergencies/{incident.Id}/status")).Content.ReadAsStringAsync();
        string dashboardAfterRetry = await (await admin.GetAsync("/api/v1/admin/dashboard/summary")).Content.ReadAsStringAsync();

        preparedToFail.Status.Should().Be(NotificationDeliveryStatus.Prepared);
        preparedToFail.FailureReason.Should().BeNull();
        cancelled.Status.Should().Be(NotificationDeliveryStatus.Cancelled);
        alreadySent.Status.Should().Be(NotificationDeliveryStatus.SimulatedSent);
        statusAfterRetry.Should().Contain("\"prepared\":1").And.Contain("\"simulatedSent\":2").And.Contain("\"failed\":0").And.Contain("\"cancelled\":1");
        dashboardAfterRetry.Should().Contain("\"prepared\":1").And.Contain("\"simulatedSent\":2").And.Contain("\"failed\":0").And.Contain("\"cancelled\":1");
        stores.Acks.Items.Should().BeEmpty();
        stores.Reports.Items.Should().BeEmpty();
        incident.Should().BeEquivalentTo(originalIncident);
        alert.Should().BeEquivalentTo(originalAlert);
        adminUser.Role.Should().Be(UserRole.Admin);
    }

    private static readonly DateTimeOffset Now = new(2026, 8, 8, 12, 0, 0, TimeSpan.Zero);
    private static Incident SeedEmergency(Stores stores, string userId) { var trip = new Trip { Id = "trip-flow", UserId = userId, Status = TripStatus.Active, StartedAtUtc = Now.AddMinutes(-20), CreatedAtUtc = Now.AddMinutes(-20) }; stores.Trips.Items.Add(trip); var incident = new Incident { Id = "incident-flow", UserId = userId, TripId = trip.Id, Source = IncidentSource.MobileDetection, Cause = IncidentCause.CountdownTimeout, RiskLevel = IncidentRiskLevel.High, Status = IncidentStatus.Open, OccurredAtUtc = Now.AddMinutes(-10), CreatedAtUtc = Now.AddMinutes(-10) }; stores.Incidents.Items.Add(incident); stores.Alerts.Items.Add(new AlertDispatchRequest { Id = "alert-flow", UserId = userId, IncidentId = incident.Id, TripId = trip.Id, Priority = AlertDispatchPriority.High, Reason = AlertDispatchReason.IncidentCreated, Status = AlertDispatchStatus.PendingDispatch, CreatedAtUtc = Now.AddMinutes(-9), RequestedAtUtc = Now.AddMinutes(-9) }); return incident; }
    private static NotificationDeliveryAttempt Attempt(string userId, string incidentId, string alertId, NotificationDeliveryStatus status, string contactId) => new() { Id = $"attempt-{contactId}", UserId = userId, IncidentId = incidentId, AlertDispatchId = alertId, TripId = "trip-flow", EmergencyContactId = contactId, Channel = NotificationChannel.Sms, Status = status, Provider = NotificationProvider.None, PreparedAtUtc = Now.AddMinutes(-8), CreatedAtUtc = Now.AddMinutes(-8) };
    private static Incident Clone(Incident i) => new() { Id = i.Id, UserId = i.UserId, TripId = i.TripId, VehicleId = i.VehicleId, MobileDeviceId = i.MobileDeviceId, SmartwatchDeviceId = i.SmartwatchDeviceId, ClientIncidentId = i.ClientIncidentId, IdempotencyKey = i.IdempotencyKey, Source = i.Source, Cause = i.Cause, RiskLevel = i.RiskLevel, Status = i.Status, Score = i.Score, Confidence = i.Confidence, GpsQuality = i.GpsQuality, RuleSetVersion = i.RuleSetVersion, ValidationPolicyVersion = i.ValidationPolicyVersion, Location = i.Location, EvidenceSummary = i.EvidenceSummary, OccurredAtUtc = i.OccurredAtUtc, CreatedAtUtc = i.CreatedAtUtc, UpdatedAtUtc = i.UpdatedAtUtc, CancelledAtUtc = i.CancelledAtUtc, ClosedAtUtc = i.ClosedAtUtc, ClosureReason = i.ClosureReason, ClosureNotes = i.ClosureNotes, ClosedByUserId = i.ClosedByUserId };
    private static AlertDispatchRequest Clone(AlertDispatchRequest a) => new() { Id = a.Id, UserId = a.UserId, IncidentId = a.IncidentId, TripId = a.TripId, VehicleId = a.VehicleId, MobileDeviceId = a.MobileDeviceId, SmartwatchDeviceId = a.SmartwatchDeviceId, ClientAlertRequestId = a.ClientAlertRequestId, IdempotencyKey = a.IdempotencyKey, Priority = a.Priority, Reason = a.Reason, Status = a.Status, RequestedAtUtc = a.RequestedAtUtc, CreatedAtUtc = a.CreatedAtUtc, UpdatedAtUtc = a.UpdatedAtUtc, CancelledAtUtc = a.CancelledAtUtc, CompletedAtUtc = a.CompletedAtUtc, Notes = a.Notes, ContactsSnapshot = a.ContactsSnapshot };
    private static async Task<User> AuthenticateAsync(HttpClient client, string email, UserRole role, Stores stores) { var register = new RegisterRequest(email, "StrongPass1!", "StrongPass1!", "Moto Rider", "+52 555", "Rider", true); await client.PostAsJsonAsync("/api/v1/auth/register", register); User user = stores.Users.Items.Single(u => u.Email == email); user.Role = role; LoginEnvelope login = (await (await client.PostAsJsonAsync("/api/v1/auth/login", new LoginRequest(email, register.Password))).Content.ReadFromJsonAsync<LoginEnvelope>())!; client.DefaultRequestHeaders.Authorization = new AuthenticationHeaderValue("Bearer", login.Data.AccessToken); return user; }
    private static WebApplicationFactory<Program> CreateFactory(Stores stores) => new WebApplicationFactory<Program>().WithWebHostBuilder(builder => { builder.UseEnvironment("Testing"); builder.ConfigureAppConfiguration((_, c) => c.AddInMemoryCollection(new Dictionary<string, string?> { ["Jwt:Issuer"] = "MotoSOS", ["Jwt:Audience"] = "MotoSOS.Clients", ["Jwt:Key"] = new string('F', 48), ["Jwt:AccessTokenMinutes"] = "15", ["Jwt:RefreshTokenDays"] = "7", ["Jwt:RefreshTokenRememberMeDays"] = "30", ["MongoDb:" + "Connection" + "String"] = string.Empty, ["MongoDb:DatabaseName"] = "MotoSOS_Test" })); builder.ConfigureTestServices(services => { services.AddSingleton<IUserRepository>(stores.Users); services.AddSingleton<IRefreshTokenRepository>(stores.RefreshTokens); services.AddSingleton<IIncidentRepository>(stores.Incidents); services.AddSingleton<ITripRepository>(stores.Trips); services.AddSingleton<IAlertDispatchRepository>(stores.Alerts); services.AddSingleton<INotificationDeliveryAttemptRepository>(stores.Attempts); services.AddSingleton<INotificationAttemptMonitorRepository>(stores.Attempts); services.AddSingleton<IAlertAcknowledgementRepository>(stores.Acks); services.AddSingleton<ILocationSharingRepository>(stores.Locations); services.AddSingleton<IMonitorLinkedContactRepository>(stores.Contacts); services.AddSingleton<IOperationalDashboardRepository>(stores.Dashboard); services.AddSingleton<IEmergencyResolutionRepository>(stores.Reports); }); });
