us == NotificationDeliveryStatus.Prepared); if (a is null) return Task.FromResult<NotificationDeliveryAttempt?>(null); a.Status = NotificationDeliveryStatus.SimulatedSent; a.Provider = NotificationProvider.Simulated; a.SimulatedSentAtUtc = now; a.UpdatedAtUtc = now; a.LastStatusChangedAtUtc = now; return Task.FromResult<NotificationDeliveryAttempt?>(a); } public Task<NotificationDeliveryAttempt?> TryMarkFailedAsync(string id, string r, DateTimeOffset now, CancellationToken ct) { NotificationDeliveryAttempt? a = Items.FirstOrDefault(x => x.Id == id && x.Status == NotificationDeliveryStatus.Prepared); if (a is null) return Task.FromResult<NotificationDeliveryAttempt?>(null); a.Status = NotificationDeliveryStatus.Failed; a.FailureReason = r; a.FailedAtUtc = now; a.UpdatedAtUtc = now; a.LastStatusChangedAtUtc = now; return Task.FromResult<NotificationDeliveryAttempt?>(a); } public Task<NotificationDeliveryAttempt?> TryResetFailedToPreparedAsync(string id, DateTimeOffset now, CancellationToken ct) { NotificationDeliveryAttempt? a = Items.FirstOrDefault(x => x.Id == id && x.Status == NotificationDeliveryStatus.Failed); if (a is null) return Task.FromResult<NotificationDeliveryAttempt?>(null); a.Status = NotificationDeliveryStatus.Prepared; a.FailureReason = null; a.FailedAtUtc = null; a.Provider = NotificationProvider.None; a.UpdatedAtUtc = now; a.LastStatusChangedAtUtc = now; return Task.FromResult<NotificationDeliveryAttempt?>(a); } public Task<long> CountByStatusAsync(NotificationDeliveryStatus s, CancellationToken ct) => Task.FromResult((long)Items.Count(a => a.Status == s)); public Task<IReadOnlyList<NotificationDeliveryAttempt>> ListByEmergencyContactIdsAsync(IReadOnlyCollection<string> ids, int p, int z, CancellationToken ct) => Task.FromResult<IReadOnlyList<NotificationDeliveryAttempt>>([]); public Task<long> CountByEmergencyContactIdsAsync(IReadOnlyCollection<string> ids, CancellationToken ct) => Task.FromResult(0L); public Task UpdateAsync(NotificationDeliveryAt